 function showError(message,target){error.textContent=message;error.hidden=false;if(target){target.setAttribute('aria-invalid','true');if(full){const panel=target.closest('[data-step]');if(panel){step=Number(panel.dataset.step);render(false)}}target.focus()}else{error.tabIndex=-1;error.focus()}}
 function validate(root){error.hidden=true;form.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));for(const el of root.querySelectorAll('input,select,textarea')){if(el.name==='website')continue;let m='';const v=el.value.trim();if(el.required&&((el.type==='checkbox'&&!el.checked)||!v))m=messages[el.name]||messages.required;else if(el.name==='start'&&(!v||v<today))m=messages.start;else if(el.name==='end'&&(!v||v<field('start').value))m=messages.end;else if(el.name==='quantity'&&(!Number.isInteger(+v)||+v<1||+v>10000))m=messages.quantity;else if(el.name==='postal'&&!/^[ABCEGHJ-NPRSTVXY]\d[ABCEGHJ-NPRSTVWXYZ][ -]?\d[ABCEGHJ-NPRSTVWXYZ]\d$/i.test(v))m=messages.postal;else if(el.name==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))m=messages.email;else if(el.name==='phone'&&(v.replace(/\D/g,'').length<7||v.replace(/\D/g,'').length>18))m=messages.phone;else if(el.name==='contact'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)&&(v.replace(/\D/g,'').length<7||v.replace(/\D/g,'').length>18))m=messages.contact;if(m){showError(m,el);return false}}return true}
